#[cfg(test)]mod cross_scope_tests{
 use super::*;use quantum_ecc::sim::Simulator;use sha3::digest::XofReader;
 struct Fixed(u8);impl XofReader for Fixed{fn read(&mut self,out:&mut[u8]){out.fill(self.0);}}
 fn fixture()->Vec<Op>{let n=u64::MAX;vec![make(K::PushCondition,n,n,n,n,0),make(K::CCX,0,1,2,n,n),make(K::PopCondition,n,n,n,n,n),make(K::PushCondition,n,n,n,n,0),make(K::CCX,0,1,3,n,n),make(K::PopCondition,n,n,n,n,n)]}
 #[test]fn separate_equal_guard_snapshots_prove_but_changed_guards_and_factors_do_not(){let n=u64::MAX;let ops=fixture();assert!(cross_scope_proof(&ops,1,4,&[0],&[3],5,2));let mut bad=ops.clone();bad[3].c_condition=BitId(1);assert!(!cross_scope_proof(&bad,1,4,&[0],&[3],5,2));let mut bad=ops.clone();bad.insert(3,make(K::BitInvert,n,n,n,0,n));assert!(!cross_scope_proof(&bad,1,5,&[0],&[4],5,2));let mut bad=ops.clone();bad.insert(3,make(K::X,n,n,0,n,n));assert!(!cross_scope_proof(&bad,1,5,&[0],&[4],5,2));}
 #[test]fn cross_scope_rewrite_preserves_every_small_value_phase_and_cost(){let ops=fixture();let lease=[1,4,4,0,1,2,0,1,3];let out=rewrite_ops(ops.clone(),&[lease],1);for pattern in[0,255,0xa5,0x5a]{let mut ra=Fixed(pattern);let mut rb=Fixed(pattern);let mut a=Simulator::new(5,2,&mut ra);let mut b=Simulator::new(5,2,&mut rb);for lane in 0..64{for q in 0..4{a.qubits[q]|=((lane>>q&1)as u64)<<lane;}a.bits[0]|=((lane>>4&1)as u64)<<lane;}b.qubits.clone_from(&a.qubits);b.bits.clone_from(&a.bits);let guard=a.bits[0];a.apply_iter(ops.iter());b.apply_iter(out.iter());assert_eq!(a.qubits,b.qubits);assert_eq!(a.bits[0],b.bits[0]);assert_eq!(a.phase,b.phase);assert_eq!(a.stats.toffoli_gates-b.stats.toffoli_gates,guard.count_ones()as u64);assert_eq!(b.qubits[4],0);}}
}
